// Pega o CSV como texto vindo do HTTP Request
const csvRaw = $json.data ?? $json.body ?? $json;
const text = (typeof csvRaw === "string") ? csvRaw : JSON.stringify(csvRaw);

const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
const headers = lines[0].split(",").map(h => h.trim());

const investimentos = lines.slice(1).map(line => {
  const cols = line.split(",").map(c => c.trim());
  const obj = {};
  headers.forEach((h, i) => obj[h] = cols[i] ?? "");

  // normaliza mínimo para número
  obj.minimo = Number(String(obj.minimo).replace(/[^\d]/g, "")) || 0;

  return obj;
});

return [{ json: { investimentos } }];

const item = $input.first().json;

const catalogo = item.investimentos ?? [];

// Aceita body como array, { clientes: [...] } ou um único cliente
const body = item.body;
const clientes = Array.isArray(body) ? body : (body?.clientes ?? [body]);

const norm = s => String(s ?? "").normalize("NFD").replace(/[\u0300-\u036f]/g, "").trim().toLowerCase();
const brl = n => "R$ " + Number(n).toLocaleString("pt-BR");

// "R$ 22.300,00" -> 22300
const paraNumero = s => parseFloat(String(s ?? "").replace(/[^\d,]/g, "").replace(",", ".")) || 0;

const abertura = {
  conservador: "perfil conservador",
  moderado: "perfil moderado",
  arrojado: "perfil arrojado"
};

return clientes.map(c => {
  const saldo = paraNumero(c.saldo);
  const perfil = norm(c.perfil);

  const doPerfil = catalogo.filter(p => norm(p.perfil) === perfil);
  const acessiveis = doPerfil.filter(p => p.minimo <= saldo);

  let mensagem;
  if (doPerfil.length === 0) {
    mensagem = `Olá, ${c.nome}! Ainda não temos recomendações para o seu perfil.`;
  } else if (acessiveis.length === 0) {
    const menor = Math.min(...doPerfil.map(p => p.minimo));
    mensagem =
      `Olá, ${c.nome}!\n\n` +
      `Para o seu ${abertura[perfil] ?? "perfil"}, o menor investimento exige ${brl(menor)}, ` +
      `acima do seu saldo atual de ${c.saldo}.`;
  } else {
    const linhas = acessiveis
      .map(p => `• ${p.produto} | mínimo ${brl(p.minimo)} | rentabilidade: ${p.rentabilidade}`)
      .join("\n");

    mensagem =
      `Olá, ${c.nome}!\n\n` +
      `Com base no seu ${abertura[perfil] ?? "perfil"} e no seu saldo de ${c.saldo}, ` +
      `estas são as opções para você:\n\n` +
      `${linhas}\n\n` +
      `Rentabilidade passada não garante resultados futuros.`;
  }

  return { json: { nome: c.nome, email: c.email, perfil: c.perfil,saldo: c.saldo, mensagem } };
});

const NO_WEBHOOK = "Webhook";
const NO_CATALOGO = "Code in JavaScript";   // o nó que converte o CSV

const tentar = fn => { try { return fn(); } catch { return undefined; } };

const entradas = $input.all().map(i => i.json);

// Catálogo: da entrada, ou direto do nó que converte o CSV
const catalogo =
  entradas.find(j => Array.isArray(j.investimentos))?.investimentos ??
  tentar(() => $(NO_CATALOGO).first().json.investimentos) ??
  [];

// Clientes: da entrada, ou direto do Webhook
const acharClientes = j => {
  const f = j?.body ?? j;
  if (Array.isArray(f)) return f;
  if (Array.isArray(f?.clientes)) return f.clientes;
  if (f?.nome) return [f];
  return [];
};

let clientes = entradas.flatMap(acharClientes).filter(c => c && c.perfil);
if (clientes.length === 0) {
  clientes = acharClientes(tentar(() => $(NO_WEBHOOK).first().json)).filter(c => c && c.perfil);
}

if (catalogo.length === 0) {
  throw new Error(`Catálogo não encontrado. Confira se o nó "${NO_CATALOGO}" existe e já foi executado.`);
}
if (clientes.length === 0) {
  throw new Error(`Nenhum cliente encontrado. Confira o body do POST e o nome do nó "${NO_WEBHOOK}".`);
}

