// ===== Configuração =====
const NO_ORIGEM = "Code in JavaScript2";   // nó que tem nome, email, produtos e mensagem
const ASSINATURA = "Atenciosamente,\nEquipe de Investimentos";
const AVISO = "Lembramos que todo investimento envolve risco e que a rentabilidade passada não garante resultados futuros.";
const ASSUNTO_PADRAO = "Opções de investimento para o seu perfil";

// Expressões que não podem aparecer (promessa de ganho)
const PROIBIDAS = [/garantid/i, /sem risco/i, /lucro certo/i, /ganho certo/i, /retorno certo/i, /n[ãa]o perca/i, /[óo]tima oportunidade/i];

// ===== Funções auxiliares =====
const tentar = fn => { try { return fn(); } catch { return undefined; } };
const esc = s => String(s ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
const emailValido = e => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(e ?? "").trim());

const extrairTexto = j =>
  j.output?.[0]?.content?.[0]?.text ?? j.message?.content ?? j.text ?? j.content?.[0]?.text ?? "";

// Remove ```json, texto antes/depois e converte para objeto
const extrairJson = txt => {
  const limpo = String(txt).replace(/```json|```/gi, "").trim();
  const ini = limpo.indexOf("{");
  const fim = limpo.lastIndexOf("}");
  if (ini === -1 || fim === -1) return null;
  return tentar(() => JSON.parse(limpo.slice(ini, fim + 1))) ?? null;
};

const normalizar = s => String(s ?? "")
  .replace(/\\n/g, "\n")            // "\n" escrito como texto
  .replace(/\r\n?/g, "\n")
  .replace(/\[[^\]]*\]/g, "")       // remove placeholders como [Seu Nome]
  .replace(/[ \t]+/g, " ")
  .replace(/ *\n */g, "\n")
  .replace(/\n{3,}/g, "\n\n")
  .trim();

// ===== Processamento =====
return $input.all().map((item, i) => {
  const origem = tentar(() => $(NO_ORIGEM).itemMatching(i).json)
              ?? tentar(() => $(NO_ORIGEM).all()[i].json)
              ?? {};

  const dados = extrairJson(extrairTexto(item.json));
  let status = "ok";
  let assunto, corpo;

  if (dados?.corpo) {
    assunto = normalizar(dados.assunto).replace(/\n/g, " ").slice(0, 80) || ASSUNTO_PADRAO;
    corpo = normalizar(dados.corpo);
  } else {
    // Se a IA não devolveu JSON válido, usa a mensagem pronta do código anterior
    status = "fallback";
    assunto = ASSUNTO_PADRAO;
    corpo = normalizar(origem.mensagem ?? "");
  }

  // Padroniza o fechamento: corpo + aviso de risco + assinatura fixa
  const idx = corpo.search(/atenciosamente/i);
  let principal = (idx >= 0 ? corpo.slice(0, idx) : corpo).trim();
  if (!/n[ãa]o garante/i.test(principal)) principal += "\n\n" + AVISO;
  const corpoTexto = `${principal}\n\n${ASSINATURA}`;

  // Sinaliza para revisão se houver promessa de ganho ou dado faltando
  if (PROIBIDAS.some(r => r.test(corpoTexto))) status = "revisar";
  if (!emailValido(origem.email)) status = "email_invalido";

  const corpoHtml = corpoTexto
    .split(/\n{2,}/)
    .map(p => `<p style="margin:0 0 12px">${esc(p).replace(/\n/g, "<br>")}</p>`)
    .join("");

  return {
    json: {
      nome: origem.nome,
      email: String(origem.email ?? "").trim(),
      assunto,
      corpo_texto: corpoTexto,
      corpo_html: `<div style="font-family:Arial,sans-serif;font-size:14px;color:#1f2937">${corpoHtml}</div>`,
      status
    }
  };
});

